// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzzed: an arbitrary address to act as the `from` actor and a uint v; the helper callee is deployed below
    function testFuzz_property(address from, uint256 v, uint256 tosCount) public {
        // keep tosCount in a reasonable range but allow zero to be excluded by the contract's require
        tosCount = bound(tosCount, 0, 5);

        // Deploy a callee that ALWAYS reverts when called with the expected selector.
        Reverter reverter = new Reverter();

        // Build a _tos array of length tosCount. If tosCount == 0, both reference and mutant revert due to require(_tos.length>0)
        // but we need the case where _tos.length > 0 and the callee call reverts to distinguish mutant vs reference.
        address[] memory tos = new address[](tosCount);
        for (uint i = 0; i < tosCount; i++) {
            // pass any address as recipients; they are irrelevant because the callee will revert
            tos[i] = address(0x1234);
        }

        // We are interested in the universal property: for ANY admissible inputs, the reference C either reverts when the external call fails
        // or returns true if all calls succeed. The mutant, however, will return false (not revert) when an external call fails.
        // We drive the scenario where tosCount > 0 and the callee reverts to observe the difference.

        // Only run the distinguishing check when tosCount > 0, otherwise both contracts behave the same (both revert on empty array).
        if (tosCount == 0) {
            // When empty, transfer should revert in both implementations; assert that reference reverts (universal property holds vacuously here).
            bool ok;
            try c.transfer(from, address(reverter), tos, v) {
                ok = true;
            } catch {
                ok = false;
            }
            // reference must revert (ok == false) for empty _tos
            assertTrue(ok == false);
            return;
        }

        // For tosCount > 0, the callee reverter will revert on being called, so reference should bubble and revert.
        bool okRef;
        try c.transfer(from, address(reverter), tos, v) {
            okRef = true;
        } catch {
            okRef = false;
        }

        // The universal rule we assert: reference NEVER returns false while completing - if a callee call fails, reference reverts instead of returning false.
        // So for this input where the callee reverts, the reference must not complete successfully (okRef must be false).
        assertTrue(okRef == false);
    }
}

// adversarial callee that always reverts when its transferFrom signature is invoked
contract Reverter {
    // match selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("revert-from-callee");
    }
    // fallback to catch any other calls as revert as well
    fallback() external payable { revert(); }
}
